// Sample-size and power calculations: epiR parallel designs, exact McNemar power, Freedman/Schoenfeld and Simon designs.
// Written for rStats.js from the published formulae and public package documentation (no R or GPL package source ported).

import { pnorm, qnorm } from "../distributions/normal.js";
import { dbinom1 } from "../distributions/binomial.js";
import { reported } from "../internal/warnings.js";
import { checkExactlyOne, isUnknown, matchChoice } from "./power.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const EPI_SSEQUB_KEYS = ["n", "power", "r", "type", "nfractional", "alpha", "sidedTest"] as const;
const EPI_SSEQUC_KEYS = ["n", "power", "r", "type", "nfractional", "alpha", "sidedTest"] as const;
const EPI_SSNINFB_KEYS = ["n", "power", "r", "type", "nfractional", "alpha", "sidedTest"] as const;
const EPI_SSNINFC_KEYS = ["n", "power", "r", "type", "nfractional", "alpha", "sidedTest"] as const;
const EPI_SSSUPB_KEYS = ["n", "power", "r", "type", "nfractional", "alpha", "sidedTest"] as const;
const EPI_SSSUPC_KEYS = ["n", "power", "r", "type", "nfractional", "alpha", "sidedTest"] as const;
const POWER_PAIRED2X2_KEYS = ["sigLevel", "alternative", "strict", "nullOddsRatio", "errbound", "tsmethod"] as const;
const SSIZE_CT_KEYS = ["alpha"] as const;
const POWER_CT_KEYS = ["alpha"] as const;
const SSIZE_EPI_KEYS = ["alpha"] as const;
const POWER_EPI_KEYS = ["alpha"] as const;
const NUM_DEPI_KEYS = ["alpha"] as const;
const PH2SIMON_KEYS = ["nmax"] as const;
// Generated by `node scripts/option-keys.mjs --write` (end)
const DEFAULT_ALPHA = 0.05;
const z = (p: number): number => qnorm(p) as number;
const phi = (x: number): number => pnorm(x) as number;
const finite = (x: number): boolean => Number.isFinite(x);
const prob = (x: number): boolean => finite(x) && x >= 0 && x <= 1;
const positive = (x: number): boolean => finite(x) && x > 0;

function checkNumber(x: number, name: string, test: (v: number) => boolean, message: string): void {
  if (typeof x !== "number") throw new TypeError(`'${name}' must be numeric`);
  if (!test(x)) throw new RangeError(message);
}
function checkAlpha(alpha: number): void {
  checkNumber(alpha, "alpha", prob, "'alpha' must be a probability in [0, 1]");
}
function splitN(n: number, r: number): [number, number] {
  return [n * r / (1 + r), n / (1 + r)];
}

/** Options shared by the epiR parallel-trial sample-size and power functions.
 * @category Effect sizes and power
 */
export interface EpiOptions {
  /** Total sample size; null/omitted when solving for sample size. */
  n?: number | null;
  /** Target power; null/omitted when solving for power. */
  power?: number | null;
  /** Treatment/control allocation ratio. Default 1. */
  r?: number;
  /** Equivalence or equality. Default "equivalence". */
  type?: "equivalence" | "equality" | (string & {});
  /** Round each group size up separately. Default false. */
  nfractional?: boolean;
  /** Significance level. Default 0.05. */
  alpha?: number;
  /** Number of tails for superiority: 1 or 2. Default 1. */
  sidedTest?: 1 | 2;
}
/** Sample-size and power result for an epiR parallel-trial design.
 * @category Effect sizes and power
 */
export interface EpiResult {
  nTotal: number;
  nTreat: number;
  nControl: number;
  nTotalUnrounded: number;
  nTreatUnrounded: number;
  nControlUnrounded: number;
  power: number;
  delta?: number;
  warnings: string[];
}
type EpiKind = "equivalence" | "noninferiority" | "superiority";
type EpiMeasure = "binary" | "continuous";

function epi(
  kind: EpiKind,
  measure: EpiMeasure,
  treat: number,
  control: number,
  sigma: number | undefined,
  delta: number | undefined,
  options: EpiOptions = {},
): EpiResult {
  
  const { n, power } = options;
  const r = options.r ?? 1;
  const alpha = options.alpha ?? DEFAULT_ALPHA;
  const nfractional = options.nfractional ?? false;
  const type = kind === "equivalence" ? matchChoice(options.type, ["equivalence", "equality"] as const) : "equivalence";
  const sides = options.sidedTest ?? 1;
  if (kind === "equivalence" && type !== "equivalence" && type !== "equality") {
    throw new RangeError("'type' should be one of “equivalence”, “equality”");
  }
  checkNumber(treat, "treat", finite, "'treat' must be finite");
  checkNumber(control, "control", finite, "'control' must be finite");
  if (measure === "binary") {
    checkNumber(treat, "treat", prob, "'treat' must be a probability in [0, 1]");
    checkNumber(control, "control", prob, "'control' must be a probability in [0, 1]");
  } else {
    checkNumber(sigma!, "sigma", positive, "'sigma' must be positive and finite");
  }
  checkNumber(r, "r", positive, "'r' must be positive and finite");
  checkAlpha(alpha);
  if (kind !== "equivalence" || type !== "equality") checkNumber(delta!, "delta", (v) => finite(v) && v >= 0, "'delta' must be nonnegative and finite");
  if (kind === "superiority" && sides !== 1 && sides !== 2) throw new RangeError("'sidedTest' must be 1 or 2");
  if (typeof nfractional !== "boolean") throw new TypeError("'nfractional' must be logical");
  checkExactlyOne([n, power], "exactly one of 'n' and 'power' must be NULL");
  if (!isUnknown(power)) {
    checkNumber(power, "power", (v) => prob(v) && v > 0 && v < 1, "'power' must be strictly between 0 and 1");
  }
  if (n !== null && n !== undefined) checkNumber(n, "n", (v) => finite(v) && v > 0, "'n' must be positive and finite");
  const D = treat - control;
  const vt = measure === "binary" ? treat * (1 - treat) : sigma! * sigma!;
  const vc = measure === "binary" ? control * (1 - control) : sigma! * sigma!;
  const equality = kind === "equivalence" && type === "equality";
  const margin = equality ? undefined : delta;
  const E = kind === "noninferiority" ? D + margin! : kind === "superiority" ? D - margin! : equality ? D : margin! - Math.abs(D);
  if (kind === "noninferiority" && E <= 0) throw new RangeError("Target power is not reachable under the specified hypotheses");
  const critical = kind === "superiority" ? z(1 - alpha / sides) : equality ? z(1 - alpha / 2) : z(1 - alpha);
  const zPower = equality || kind !== "equivalence" ? z(power ?? 0.8) : z(1 - (1 - (power ?? 0.8)) / 2);
  let nTreat: number;
  let nControl: number;
  let nTreatUnrounded: number;
  let nControlUnrounded: number;
  let actualPower: number;
  if (isUnknown(n)) {
    if (E === 0) {
      nTreatUnrounded = Infinity;
      nControlUnrounded = Infinity;
    } else {
      nControlUnrounded = ((critical + zPower) ** 2 * (vt / r + vc)) / (E * E);
      nTreatUnrounded = r * nControlUnrounded;
    }
    if (nfractional) {
      nTreat = nTreatUnrounded;
      nControl = nControlUnrounded;
    } else {
      nControl = Math.ceil(nControlUnrounded);
      // Public epiR outputs show method-specific integer allocation. For
      // continuous equivalence and superiority, round the control arm first
      // and then round r * nControl; the other four methods round each
      // unrounded arm independently. epiR is inconsistent for some ratios
      // (including fractional outputs with nfractional=FALSE); rStats keeps
      // the requested integer-size contract instead of returning fractions.
      const ratioFromRoundedControl = (kind === "equivalence" && measure === "continuous") || kind === "superiority";
      nTreat = ratioFromRoundedControl ? Math.ceil(r * nControl) : Math.ceil(nTreatUnrounded);
    }
    actualPower = power!;
  } else {
    [nTreatUnrounded, nControlUnrounded] = splitN(n, r);
    nTreat = nfractional ? nTreatUnrounded : Math.ceil(nTreatUnrounded);
    nControl = nfractional ? nControlUnrounded : Math.ceil(nControlUnrounded);
    const se = Math.sqrt(vt / nTreat + vc / nControl);
    if (kind === "equivalence" && !equality) {
      // User-selected TOST probability: the intersection of the two one-sided rejection events.
      actualPower = Math.max(0, phi((delta! - D) / se - z(1 - alpha)) + phi((delta! + D) / se - z(1 - alpha)) - 1);
    } else if (equality) {
      actualPower = phi(Math.abs(D) / se - z(1 - alpha / 2)) + phi(-Math.abs(D) / se - z(1 - alpha / 2));
    } else if (kind === "noninferiority") {
      actualPower = phi((D + delta!) / se - z(1 - alpha));
    } else {
      const e = Math.abs(D - delta!) / se;
      actualPower = phi(e - critical) + phi(-e - critical);
    }
  }
  const result: EpiResult = {
    nTotal: nTreat + nControl,
    nTreat,
    nControl,
    nTotalUnrounded: nTreatUnrounded + nControlUnrounded,
    nTreatUnrounded,
    nControlUnrounded,
    power: actualPower,
    ...(margin === undefined ? {} : { delta: margin }),
    warnings: [],
  };
  return result;
}

/** Equivalence/equality sample size or power for two proportions. Equivalent to `epiR::epi.ssequb()` in R.
 * @param treat Expected treatment-group proportion.
 * @param control Expected control-group proportion.
 * @param delta Equivalence margin; pass null for equality.
 * @param options Sample-size, power and allocation options.
 * @returns The fractional and requested group sizes, and power. The sample-size formula follows epiR's expression and is not an exact inverse of the TOST power calculation.
 * @example
 * ```ts
 * epiSsequb(0.5, 0.45, 0.1, { n: 120 }).power;
 * ```
 * @category Effect sizes and power
 */
export function epiSsequb(treat: number, control: number, delta: number | null, options: EpiOptions = {}): EpiResult {
  checkOptions(options, EPI_SSEQUB_KEYS, "epiSsequb"); // generated: option-keys.mjs
  return reported("epiSsequb", epi("equivalence", "binary", treat, control, undefined, delta ?? undefined, options));
}
/** Equivalence/equality sample size or power for two means. Equivalent to `epiR::epi.ssequc()` in R.
 * @param treat Expected treatment-group mean.
 * @param control Expected control-group mean.
 * @param sigma Common standard deviation.
 * @param delta Equivalence margin; pass null for equality.
 * @param options Sample-size, power and allocation options.
 * @returns The fractional and requested group sizes, and power. The sample-size formula follows epiR's expression and is not an exact inverse of the TOST power calculation.
 * @example
 * ```ts
 * epiSsequc(20, 21, 10, 5, { n: 120 }).power;
 * ```
 * @category Effect sizes and power
 */
export function epiSsequc(treat: number, control: number, sigma: number, delta: number | null, options: EpiOptions = {}): EpiResult {
  checkOptions(options, EPI_SSEQUC_KEYS, "epiSsequc"); // generated: option-keys.mjs
  const out = epi("equivalence", "continuous", treat, control, sigma, delta ?? undefined, options);
  return reported("epiSsequc", out);
}
