/** Options for the exact paired McNemar power calculation.
 * @category Effect sizes and power
 */
export interface PowerPaired2x2Options {
  sigLevel?: number;
  alternative?: "two.sided" | "one.sided" | (string & {});
  strict?: boolean;
  nullOddsRatio?: number;
  errbound?: number;
  tsmethod?: "central" | "minlike" | "blaker" | (string & {});
}
/** Result of the exact paired McNemar power calculation.
 * @category Effect sizes and power
 */
export interface PowerPaired2x2Result {
  power: number;
  npairs: number;
  pb: number;
  pc: number;
  sigLevel: number;
  alternative: "two.sided" | "one.sided";
  nullOddsRatio: number;
  note: string;
  method: string;
  warnings: string[];
}
function binomialMasses(n: number, p: number): number[] {
  const out = new Array<number>(n + 1).fill(0);
  if (p === 0) { out[0] = 1; return out; }
  if (p === 1) { out[n] = 1; return out; }
  const mode = Math.floor((n + 1) * p);
  out[mode] = Math.exp((n * Math.log1p(-p)) + mode * Math.log(p / (1 - p)) +
    Array.from({ length: mode }, (_, i) => Math.log(n - i) - Math.log(i + 1)).reduce((a, b) => a + b, 0));
  for (let k = mode; k > 0; k--) out[k - 1] = out[k]! * (k / (n - k + 1)) * ((1 - p) / p);
  for (let k = mode; k < n; k++) out[k + 1] = out[k]! * ((n - k) / (k + 1)) * (p / (1 - p));
  return out;
}
/** Exact power of McNemar's test for paired binary outcomes. Equivalent to `exact2x2::powerPaired2x2()` in R.
 * @param pb Probability of a discordant pair with control 0 and treatment 1.
 * @param pc Probability of a discordant pair with control 1 and treatment 0.
 * @param npairs Number of pairs.
 * @param options Test options; `errbound` is retained for API compatibility, but the exact sum is always evaluated.
 * @returns The power and test settings.
 * @example
 * ```ts
 * powerPaired2x2(0.5, 0.3, 40).power;
 * ```
 * @category Effect sizes and power
 */
export function powerPaired2x2(pb: number, pc: number, npairs: number, options: PowerPaired2x2Options = {}): PowerPaired2x2Result {
  checkOptions(options, POWER_PAIRED2X2_KEYS, "powerPaired2x2"); // generated: option-keys.mjs
  const sigLevel = options.sigLevel ?? DEFAULT_ALPHA;
  const alternative = matchChoice(options.alternative, ["two.sided", "one.sided"] as const);
  const strict = options.strict ?? false;
  const nullOddsRatio = options.nullOddsRatio ?? 1;
  const errbound = options.errbound ?? 1e-6;
  const tsmethod = matchChoice(options.tsmethod, ["central", "minlike", "blaker"] as const);
  checkNumber(pb, "pb", prob, "'pb' must be in [0, 1]");
  checkNumber(pc, "pc", prob, "'pc' must be in [0, 1]");
  checkNumber(npairs, "npairs", (v) => Number.isSafeInteger(v) && v >= 0 && v <= 100000, "'npairs' must be a nonnegative safe integer");
  checkAlpha(sigLevel);
  checkNumber(nullOddsRatio, "nullOddsRatio", positive, "'nullOddsRatio' must be positive and finite");
  checkNumber(errbound, "errbound", (v) => finite(v) && v >= 0, "'errbound' must be nonnegative and finite");
  if (pb + pc > 1) throw new RangeError("probabilities must be finite, non-negative and not all 0");
  if (alternative !== "two.sided" && alternative !== "one.sided") throw new RangeError("'alternative' should be one of “two.sided”, “one.sided”");
  if (!["central", "minlike", "blaker"].includes(tsmethod)) throw new RangeError("'tsmethod' should be one of “central”, “minlike”, “blaker”");
  const q = pb + pc;
  const pAlt = q === 0 ? 0.5 : pb / q;
  const pNull = nullOddsRatio / (1 + nullOddsRatio);
  const direction = pb >= pc ? 1 : -1;
  const useBoth = alternative === "two.sided" && strict && tsmethod !== "blaker";
  const useOne = alternative === "one.sided";
  const massM = binomialMasses(npairs, q);
  let firstM = 0, lastM = npairs;
  if (errbound > 0) {
    let tail = 0;
    while (firstM <= npairs && (tail += massM[firstM]!) <= errbound / 2) firstM++;
    tail = 0;
    while (lastM >= 0 && (tail += massM[lastM]!) <= errbound / 2) lastM--;
  }
  let power = 0;
  for (let m = firstM; m <= lastM; m++) {
    const wm = massM[m]!;
    if (wm === 0) continue;
    const alt = binomialMasses(m, pAlt);
    const nul = binomialMasses(m, pNull);
    let lower = 0, upper = 0;
    const lowerTail = new Array<number>(m + 1);
    const upperTail = new Array<number>(m + 1);
    for (let x = 0; x <= m; x++) { lower += nul[x]!; lowerTail[x] = lower; }
    for (let x = m; x >= 0; x--) { upper += nul[x]!; upperTail[x] = upper; }
    for (let x = 0; x <= m; x++) {
      const lo = lowerTail[x]!;
      const hi = upperTail[x]!;
      let reject: boolean;
      if (useOne) reject = direction > 0 ? hi <= sigLevel : lo <= sigLevel;
      else if (useBoth) reject = (lo <= sigLevel / 2 || hi <= sigLevel / 2);
      else reject = direction > 0 ? hi <= sigLevel / 2 : lo <= sigLevel / 2;
      if (reject) power += wm * alt[x]!;
    }
  }
  const note = `errbound= ${errbound === 0 ? "0" : errbound >= 0.001 ? String(errbound) : `${errbound.toExponential(0).replace(/e([+-]?)(\\d+)$/, (_m, sign, exp) => `e${sign || "+"}${exp.padStart(2, "0")}`)}`}${pb + pc === 1 ? "  no non-informative pairs: pa+pd=0" : ""}`;
  const method = "Power for McNemar's Exact Test" +
    (useBoth ? ", including power to reject in the wrong direction" : "") +
    (tsmethod === "central" && options.tsmethod !== undefined ? `, using (tsmethod=${tsmethod})` :
      tsmethod === "minlike" ? `, using (tsmethod=${tsmethod})` :
      tsmethod === "blaker" ? `, using (tsmethod=${tsmethod})` : "");
  return reported("powerPaired2x2", { power, npairs, pb, pc, sigLevel, alternative, nullOddsRatio, note, method, warnings: [] });
}

/** Significance-level options for survival sample-size calculations.
 * @category Effect sizes and power
 */
export interface SurvivalOptions { alpha?: number; }
/** Result of a Freedman clinical-trial sample-size calculation.
 * @category Effect sizes and power
 */
export interface SSizeCTResult { nE: number; nC: number; }
/** Freedman clinical-trial power. Equivalent to `powerSurvEpi::powerCT()` in R.
 * @param nE Experimental-group sample size.
 * @param nC Control-group sample size.
 * @param pE Experimental-group event probability.
 * @param pC Control-group event probability.
 * @param RR Experimental/control hazard ratio.
 * @param options Significance level.
 * @returns The normal-approximation power.
 * @example
 * ```ts
 * powerCT(200, 200, 0.3707, 0.489, 0.7);
 * ```
 * @category Effect sizes and power
 */
export function powerCT(nE: number, nC: number, pE: number, pC: number, RR: number, options: SurvivalOptions = {}): number {
  checkOptions(options, POWER_CT_KEYS, "powerCT"); // generated: option-keys.mjs
  const alpha = options.alpha ?? DEFAULT_ALPHA; checkAlpha(alpha);
  for (const [v, name] of [[nE,"nE"],[nC,"nC"]] as const) checkNumber(v,name,positive,`'${name}' must be positive and finite`);
  for (const [v, name] of [[pE,"pE"],[pC,"pC"]] as const) checkNumber(v,name,prob,`'${name}' must be in [0, 1]`);
  checkNumber(RR,"RR",positive,"'RR' must be positive and finite");
  const k = nE / nC;
  const m = nE * pE + nC * pC;
  return phi(Math.sqrt(k * m) * Math.abs(RR - 1) / (k * RR + 1) - z(1 - alpha / 2));
}
/** Freedman clinical-trial sample size. Equivalent to `powerSurvEpi::ssizeCT()` in R.
 * @param power Target power.
 * @param k Experimental/control allocation ratio.
 * @param pE Experimental-group event probability.
 * @param pC Control-group event probability.
 * @param RR Experimental/control hazard ratio.
 * @param options Significance level.
 * @returns The integer sample sizes in the two groups.
 * @example
 * ```ts
 * ssizeCT(0.8, 1, 0.3707, 0.489, 0.7);
 * ```
 * @category Effect sizes and power
 */
export function ssizeCT(power: number, k: number, pE: number, pC: number, RR: number, options: SurvivalOptions = {}): SSizeCTResult {
  checkOptions(options, SSIZE_CT_KEYS, "ssizeCT"); // generated: option-keys.mjs
  const alpha = options.alpha ?? DEFAULT_ALPHA; checkAlpha(alpha);
  checkNumber(power,"power",(v)=>prob(v)&&v>0&&v<1,"'power' must be strictly between 0 and 1");
  checkNumber(k,"k",positive,"'k' must be positive and finite");
  checkNumber(pE,"pE",prob,"'pE' must be in [0, 1]"); checkNumber(pC,"pC",prob,"'pC' must be in [0, 1]");
  checkNumber(RR,"RR",positive,"'RR' must be positive and finite");
  const zz = z(1-alpha/2)+z(power);
  const m = (1/k)*(((k*RR+1)/(RR-1))**2)*(zz*zz);
  const den = k*pE+pC;
  return { nE: Math.ceil(m*k/den), nC: Math.ceil(m/den) };
}
/** Schoenfeld/Latouche Cox-model power. Equivalent to `powerSurvEpi::powerEpi()` in R.
 * @param n Total sample size.
 * @param theta Hazard ratio.
 * @param p Prevalence of the binary covariate.
 * @param psi Event proportion.
 * @param rho2 Squared correlation with another covariate.
 * @param options Significance level.
 * @returns The normal-approximation power.
 * @example
 * ```ts
 * powerEpi(139, 2, 0.39, 0.505, 0.132 ** 2);
 * ```
 * @category Effect sizes and power
 */
export function powerEpi(n: number, theta: number, p: number, psi: number, rho2: number, options: SurvivalOptions = {}): number {
  checkOptions(options, POWER_EPI_KEYS, "powerEpi"); // generated: option-keys.mjs
  const alpha=options.alpha??DEFAULT_ALPHA; checkAlpha(alpha);
  checkNumber(n,"n",positive,"'n' must be positive and finite"); checkNumber(theta,"theta",positive,"'theta' must be positive and finite");
  checkNumber(p,"p",prob,"'p' must be in [0, 1]"); checkNumber(psi,"psi",prob,"'psi' must be in [0, 1]");
  checkNumber(rho2,"rho2",prob,"'rho2' must be in [0, 1]");
  const info = n * Math.log(theta)**2 * p*(1-p)*psi*(1-rho2);
  return phi(Math.sqrt(info)-z(1-alpha/2));
}
/** Schoenfeld/Latouche total sample size. Equivalent to `powerSurvEpi::ssizeEpi()` in R.
 * @param power Target power.
 * @param theta Hazard ratio.
 * @param p Prevalence of the binary covariate.
 * @param psi Event proportion.
 * @param rho2 Squared correlation with another covariate.
 * @param options Significance level.
 * @returns The integer total sample size.
 * @example
 * ```ts
 * ssizeEpi(0.8, 2, 0.39, 0.505, 0.132 ** 2);
 * ```
 * @category Effect sizes and power
 */
export function ssizeEpi(power: number, theta: number, p: number, psi: number, rho2: number, options: SurvivalOptions = {}): number {
  checkOptions(options, SSIZE_EPI_KEYS, "ssizeEpi"); // generated: option-keys.mjs
  const alpha=options.alpha??DEFAULT_ALPHA; checkAlpha(alpha);
  checkNumber(power,"power",prob,"'power' must be in [0, 1]");
  checkNumber(theta,"theta",positive,"'theta' must be positive and finite");
  checkNumber(p,"p",prob,"'p' must be in [0, 1]"); checkNumber(psi,"psi",prob,"'psi' must be in [0, 1]");
  checkNumber(rho2,"rho2",prob,"'rho2' must be in [0, 1]");
  const den = Math.log(theta)**2*p*(1-p)*psi*(1-rho2);
  return Math.ceil((z(1-alpha/2)+z(power))**2/den);
}
/** Schoenfeld/Latouche required event count. Equivalent to `powerSurvEpi::numDEpi()` in R.
 * @param power Target power.
 * @param theta Hazard ratio.
 * @param p Prevalence of the binary covariate.
 * @param rho2 Squared correlation with another covariate.
 * @param options Significance level.
 * @returns The integer number of events required.
 * @example
 * ```ts
 * numDEpi(0.8, 2, 0.39, 0.132 ** 2);
 * ```
 * @category Effect sizes and power
 */
export function numDEpi(power: number, theta: number, p: number, rho2: number, options: SurvivalOptions = {}): number {
  checkOptions(options, NUM_DEPI_KEYS, "numDEpi"); // generated: option-keys.mjs
  const alpha=options.alpha??DEFAULT_ALPHA; checkAlpha(alpha);
  checkNumber(power,"power",(v)=>prob(v)&&v>0&&v<1,"'power' must be strictly between 0 and 1");
  checkNumber(theta,"theta",positive,"'theta' must be positive and finite");
  checkNumber(p,"p",prob,"'p' must be in [0, 1]"); checkNumber(rho2,"rho2",prob,"'rho2' must be in [0, 1]");
  const den = Math.log(theta)**2*p*(1-p)*(1-rho2);
  return Math.ceil((z(1-alpha/2)+z(power))**2/den);
}

/** A feasible two-stage Simon candidate.
 * @category Effect sizes and power
 */
export interface SimonRow { r1:number; n1:number; r:number; n:number; enP0:number; petP0:number; }
/** A selected Simon design and its interval of q values.
 * @category Effect sizes and power
 */
export interface SimonDesign extends SimonRow { qLo:number; qHi:number; }
/** Candidate designs and selected minimax, optimal and admissible Simon designs.
 * @category Effect sizes and power
 */
export interface SimonDesignResult { out: SimonRow[]; minimax: SimonDesign; optimal: SimonDesign; admissible: SimonDesign[]; pu:number; pa:number; alpha:number; beta:number; nmax:number; warnings:string[]; }
function cumulative(mass:readonly number[]):number[] {
  const out=new Array<number>(mass.length); let sum=0;
  for(let i=0;i<mass.length;i++){sum+=mass[i]!;out[i]=sum;}
  return out;
}
function designProb(r1:number,r:number,p0Stage1:readonly number[],p1Stage1:readonly number[],p0Stage2Cdf:readonly number[],p1Stage2Cdf:readonly number[]):[number,number] {
  let alpha=0,beta=0;
  // A trial that stops for futility after stage 1 is a type-II error under pa.
  beta = p1Stage1.slice(0, r1 + 1).reduce((sum, value) => sum + value, 0);
  for(let x=r1+1;x<p0Stage1.length;x++){
    const j=r-x;
    const c0=j<0?0:p0Stage2Cdf[Math.min(j,p0Stage2Cdf.length-1)]!;
    const c1=j<0?0:p1Stage2Cdf[Math.min(j,p1Stage2Cdf.length-1)]!;
    alpha += p0Stage1[x]!*(1-c0);
    beta += p1Stage1[x]!*c1;
  }
  return [alpha,beta];
}
/** Enumerates Simon's two-stage Phase II designs. Equivalent to `clinfun::ph2simon()` in R.
 * @param pu Unacceptable response rate.
 * @param pa Desirable response rate.
 * @param ep1 Maximum type-I error at pu.
 * @param ep2 Maximum type-II error at pa.
 * @param options Maximum total sample size, at most 1000.
 * @returns Candidate rows and structured minimax, optimal and admissible designs.
 * @example
 * ```ts
 * ph2simon(0.2, 0.4, 0.05, 0.1).minimax.n;
 * ```
 * @category Effect sizes and power
 */
export function ph2simon(pu:number,pa:number,ep1:number,ep2:number,options: {nmax?:number} = {}):SimonDesignResult {
  checkOptions(options, PH2SIMON_KEYS, "ph2simon"); // generated: option-keys.mjs
  const nmax=options.nmax??100;
  for(const [v,name] of [[pu,"pu"],[pa,"pa"],[ep1,"ep1"],[ep2,"ep2"]] as const) checkNumber(v,name,prob,`'${name}' must be in [0, 1]`);
  checkNumber(nmax,"nmax",(v)=>Number.isInteger(v)&&v>=1&&v<=1000,"nmax cannot exceed 1000");
  const masses0=Array.from({length:nmax+1},(_,size)=>binomialMasses(size,pu));
  const masses1=Array.from({length:nmax+1},(_,size)=>binomialMasses(size,pa));
  const cdfs0=masses0.map(cumulative), cdfs1=masses1.map(cumulative);
  const out:SimonRow[]=[];
  for(let n=2;n<=nmax;n++){
    let best:SimonRow|undefined;
    for(let n1=1;n1<n && (best===undefined || n1<best.enP0);n1++){
      const n2=n-n1;
      const p0Stage1=masses0[n1]!, p1Stage1=masses1[n1]!;
      const p0Stage2Cdf=cdfs0[n2]!, p1Stage2Cdf=cdfs1[n2]!;
      const p0Stage1Cdf=cdfs0[n1]!;
      for(let r1=0;r1<n1;r1++){
        const pet=p0Stage1Cdf[r1]!;
        const en=n1+n2*(1-pet);
        // Match clinfun: choose the largest final cutoff r satisfying both error constraints.
        let low=r1,high=n-1,rFound=-1;
        while(low<=high){
          const mid=Math.floor((low+high)/2);
          const [,bAlt]=designProb(r1,mid,p0Stage1,p1Stage1,p0Stage2Cdf,p1Stage2Cdf);
          if(bAlt<=ep2){rFound=mid;low=mid+1;} else high=mid-1;
        }
        if(rFound>=0){
          const [a]=designProb(r1,rFound,p0Stage1,p1Stage1,p0Stage2Cdf,p1Stage2Cdf);
          if(a>ep1) rFound=-1;
        }
        if(rFound>=0 && (best===undefined || en<best.enP0)){
          best={r1,n1,r:rFound,n,enP0:en,petP0:pet};
        }
      }
    }
    if(best) out.push(best);
  }
  if(out.length===0) throw new Error(`  No feasible solution found. \n\tIncrease maximum sample size.  Current nmax value = ${nmax}.`);
  const frontier=out.filter((row,i)=>!out.some((other,j)=>j!==i&&other.n<=row.n&&other.enP0<=row.enP0&&(other.n<row.n||other.enP0<row.enP0)));
  const hull:SimonRow[]=[];
  const crossing=(a:SimonRow,b:SimonRow)=> (a.enP0-b.enP0)/((b.n-a.n)+(a.enP0-b.enP0));
  for(const row of frontier){
    hull.push(row);
    while(hull.length>=3){
      const a=hull[hull.length-3]!,b=hull[hull.length-2]!,c=hull[hull.length-1]!;
      if(crossing(a,b)>crossing(b,c)) break;
      hull.splice(hull.length-2,1);
    }
  }
  const selected:SimonDesign[]=hull.map((row,i)=>{
    const qLo=i===hull.length-1?0:crossing(row,hull[i+1]!);
    const qHi=i===0?1:crossing(hull[i-1]!,row);
    return {...row,qLo,qHi};
  });
  const minimax=selected[0]!;
  const optimal=selected.reduce((a,b)=>b.enP0<a.enP0?b:a);
  const admissible=selected;
  const warnings:string[]=[];
  if(optimal.n>=nmax-1) warnings.push(`  Optimal sample size too close to nmax. \n  Try increasing nmax (current value = ${nmax})\n`);
  return reported("ph2simon",{out,minimax,optimal,admissible,pu,pa,alpha:ep1,beta:ep2,nmax,warnings});
}
